-- STAGING ONLY 479: authoritative UID632 successor retaining all 22 genuine Job Card operations.
BEGIN;SET LOCAL statement_timeout='180s';SELECT pg_advisory_xact_lock(hashtextextended('pdc-staging-479-uid632-complete-operations',0));
DO $g$ BEGIN IF current_user<>'postgres' OR (SELECT count(*) FROM public.pdc_staging_environment_sentinel WHERE singleton AND project_ref='cdsmnqxtyyoeoznmbidd')<>1 OR to_regclass('public.pdc_production_environment_sentinel') IS NOT NULL OR NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20260827028000' AND name='478_complete_jobcard_operation_contract') OR EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version~'^[0-9]{14}$' AND version>'20260827028000') OR (SELECT count(*) FROM public.pdc_authenticated_email_operation_lines WHERE source_hash='141354ac4a92cb01c031ee782450e56451061d7ba2f68b8fb79aca2a3d503a96')<>8 OR NOT EXISTS(SELECT 1 FROM public.pdc_jobcard_attachment_import_receipts WHERE receipt_id='e7571359-c84c-493f-8376-d8384ea70b6f'::uuid AND operation_count=8 AND estimated_hours_sum=9.43 AND attachment_source_hash='9806dadf50ffd2acdd035b662672e9158b94091f848a01db0c1ae021186a993a') OR NOT EXISTS(SELECT 1 FROM public.vehicles WHERE id='99518513-5293-5619-a06e-9b4323754838'::uuid AND stock_number_normalized='13000776' AND job_card_number='J139125495' AND vin_normalized='MR0MABAV402402341' AND deleted_at IS NULL) THEN RAISE EXCEPTION 'PDC_479_TARGET_OR_UID632_EVIDENCE_MISMATCH';END IF;END $g$;
CREATE TEMP TABLE pdc479_manifest ON COMMIT DROP AS SELECT (x->>'source_row_no')::integer source_row_no,x->>'operation_no' operation_no,x->>'work_key' work_key,x->>'description' description,CASE WHEN jsonb_typeof(x->'estimated_hours')='number' THEN (x->>'estimated_hours')::numeric ELSE NULL END estimated_hours,x->>'estimated_hours_source' estimated_hours_source FROM jsonb_array_elements($ops$[{"description":"COMPLEMENTARY FULL TANK OF FUEL [ 0.00 ] 05H3A CN Complementary Full Tank of Fuel HiLux 4x4 2.8L Dsl D/C/C 6AT WorkMate 2U22310 001 Build Date: 26/05/26 Alt Model: GUN226R-DTTLXQ3","estimated_hours":0.0,"estimated_hours_source":"job_card","operation_no":"OP1","source_row_no":1,"work_key":"fitting"},{"description":"Pre-Delivery (Commercial) [ 0.00 ] V CN Pre-Delivery (Commercial)","estimated_hours":0.0,"estimated_hours_source":"job_card","operation_no":"OP2","source_row_no":2,"work_key":"fitting"},{"description":"Steel Bull Bar - Commercial [ 5.18 ] V SN Fit accessory : Steel Bull Bar - Commercial (BB003) Notes :","estimated_hours":5.18,"estimated_hours_source":"job_card","operation_no":"OP3","source_row_no":3,"work_key":"fitting"},{"description":"Tow Bar [For 2550mm/2100mm/1800mm Tray Body] with Small Round Plug (Long Tongue) [ 1.58 ] V SN Fit accessory : Tow Bar [For 2550mm/2100mm/1800mm Tray Body] with Small Round Plug (L","estimated_hours":1.58,"estimated_hours_source":"job_card","operation_no":"OP4","source_row_no":4,"work_key":"fitting"},{"description":"Wheel Nut Indicator Set [ 0.25 ] V SN Fit accessory : Wheel Nut Indicator Set (AW005) Notes : To suit 21mm wheel nut, steel and alloy","estimated_hours":0.25,"estimated_hours_source":"job_card","operation_no":"OP5","source_row_no":5,"work_key":"fitting"},{"description":"1.2m Whip Flag with Spring Base to Suit Minebars - No Light [ 0.10 ] V CN 1.2m Whip Flag with Spring to suit PMB/Narva Minebars","estimated_hours":0.1,"estimated_hours_source":"job_card","operation_no":"OP6","source_row_no":6,"work_key":"owner_supplied_document"},{"description":"1.5 Kg Fire Extinuisher to LHF floor [ 0.50 ] V CN 1.5Kg Fire Ext Frt LHF Pass Seat SN Fit 1.5 kg fire Ext to lhf floor","estimated_hours":0.5,"estimated_hours_source":"job_card","operation_no":"OP7","source_row_no":7,"work_key":"fitting"},{"description":"Battery Isolator with Locksafe Cover mounted Under Bonnet - Hilux [ 0.30 ] V","estimated_hours":0.3,"estimated_hours_source":"job_card","operation_no":"OP8","source_row_no":8,"work_key":"owner_supplied_document"},{"description":"firstaid kit big [ 0.00 ] V CN first aid kit big SN Supply big first aid kit","estimated_hours":0.0,"estimated_hours_source":"job_card","operation_no":"OP9","source_row_no":9,"work_key":"owner_supplied_document"},{"description":"Headlamps Auto On & Hand Brake OFF Alarm Combo - DYNAMCO - Hilux [ 1.50 ] V CN Headlamps Auto On & Hand Brake OFF Alarm Combo - DYNAMCO","estimated_hours":1.5,"estimated_hours_source":"job_card","operation_no":"OP10","source_row_no":10,"work_key":"owner_supplied_document"},{"description":"MINE BAR WITH FORWARD FACING INDICATORS, DUAL SOUND REVERSE BUZZER [ 3.50 ] V WITH SWITCH ON DASH - ACOT500 CN MINE BAR -Basic -FRT IND- D/S R/BUZZER OWN SWITCH","estimated_hours":3.5,"estimated_hours_source":"job_card","operation_no":"OP11","source_row_no":11,"work_key":"fabrication"},{"description":"SUB - MMT 2 Row Canvas Seat Covers [ 0.00 ] V CN MMT 2 ROWS SEAT COVERS CANVAS","estimated_hours":0.0,"estimated_hours_source":"job_card","operation_no":"OP12","source_row_no":12,"work_key":"fitting"},{"description":"PMB002 -Dual Cab ROPS Certified HD Steel Tray 1850mm x 1900mm (232kg) [ 0.00 ] V CN PMB002 - PMB HD Steel Tray with ROPS","estimated_hours":0.0,"estimated_hours_source":"job_card","operation_no":"OP13","source_row_no":13,"work_key":"fabrication"},{"description":"Spare Tyre Holder To Suit PMB Cab Rack Each [ 0.00 ] V CN PMBA01 - Spare Tyre holder to suit PMB Cabrack","estimated_hours":0.0,"estimated_hours_source":"job_card","operation_no":"OP14","source_row_no":14,"work_key":"tyre"},{"description":"Certified Mesh Cab Rack Barrier Rated To 60kg With Certification Plate [ 0.00 ] V CN PMBA02 - Certified Mesh Cab Rack Barrier","estimated_hours":0.0,"estimated_hours_source":"job_card","operation_no":"OP15","source_row_no":15,"work_key":"owner_supplied_document"},{"description":"Reverse Camera Relocation Bracket Required For All Vehicles With Standard Reverse [ 0.00 ] V Camera","estimated_hours":0.0,"estimated_hours_source":"job_card","operation_no":"OP16","source_row_no":16,"work_key":"owner_supplied_document"},{"description":"Wheel Chock's & Holder Mounted CN PMBA63 - Mounted Wheel Chocks and Holder [ 0.40 ] V","estimated_hours":0.4,"estimated_hours_source":"job_card","operation_no":"OP17","source_row_no":17,"work_key":"owner_supplied_document"},{"description":"Mount Safety Triangles & Holder to L/H side of Headboard or Cargo area [ 0.30 ] V CN Safety Triangle Kit Mounted to L/H Headboard/Cargo area [ 0.00 ] V","estimated_hours":0.3,"estimated_hours_source":"job_card","operation_no":"OP18","source_row_no":18,"work_key":"owner_supplied_document"},{"description":"Hilux Additional Spare 7.5x17 Steel Rim 265/65R17 Factory Tyre CN Second Spare Steel Rim & Factory Tyre [ 0.00 ] V","estimated_hours":0.0,"estimated_hours_source":"job_card","operation_no":"OP19","source_row_no":19,"work_key":"tyre"},{"description":"SUB CALL SIGNS CN SUB CALL SIGNS","estimated_hours":null,"estimated_hours_source":"owner_supplied_document_unknown","operation_no":"OP20","source_row_no":20,"work_key":"owner_supplied_document"},{"description":"Reflective Stripes - Yellow CN SUB reflective stripes Yellow SN FIT REFLECTIVE STRIPES [ 1.50 ] V","estimated_hours":1.5,"estimated_hours_source":"job_card","operation_no":"OP21","source_row_no":21,"work_key":"sublet"},{"description":"GME XRS-370c with PMB Standard Aerial CN UHF GME XRS-370c with Standard Aerial Printed 26/08/2026 08:25:10","estimated_hours":null,"estimated_hours_source":"owner_supplied_document_unknown","operation_no":"OP22","source_row_no":22,"work_key":"electrical"}]$ops$::jsonb) x;
DO $manifest$ BEGIN IF (SELECT count(*) FROM pdc479_manifest)<>22 OR (SELECT count(*) FROM pdc479_manifest WHERE estimated_hours=0)<>9 OR (SELECT count(*) FROM pdc479_manifest WHERE estimated_hours IS NULL)<>2 OR (SELECT count(*) FROM pdc479_manifest WHERE work_key='owner_supplied_document')<>9 OR (SELECT array_agg(operation_no ORDER BY source_row_no) FROM pdc479_manifest)<>ARRAY['OP1','OP2','OP3','OP4','OP5','OP6','OP7','OP8','OP9','OP10','OP11','OP12','OP13','OP14','OP15','OP16','OP17','OP18','OP19','OP20','OP21','OP22'] THEN RAISE EXCEPTION 'PDC_479_MANIFEST_INVALID';END IF;IF EXISTS(SELECT 1 FROM public.pdc_authenticated_email_operation_lines l JOIN pdc479_manifest m USING(operation_no) WHERE l.source_hash='141354ac4a92cb01c031ee782450e56451061d7ba2f68b8fb79aca2a3d503a96' AND (l.work_key,l.description,l.estimated_hours,l.estimated_hours_source) IS DISTINCT FROM (m.work_key,m.description,m.estimated_hours,m.estimated_hours_source)) THEN RAISE EXCEPTION 'PDC_479_EXISTING_LINE_DRIFT';END IF;END $manifest$;
CREATE TEMP TABLE pdc479_inserted(operation_line_id uuid,operation_no text) ON COMMIT DROP;WITH ins AS(INSERT INTO public.pdc_authenticated_email_operation_lines(import_receipt_id,vehicle_id,source_hash,source_uid,operation_no,work_key,description,estimated_hours,estimated_hours_source,operation_fingerprint,job_card_number,source_row_no,source_contract) SELECT 'caf85a35-5ee9-4266-946d-273a9670b8af'::uuid,'99518513-5293-5619-a06e-9b4323754838'::uuid,'141354ac4a92cb01c031ee782450e56451061d7ba2f68b8fb79aca2a3d503a96','pdc-jc-159:40a0d19ac708da3edf37b798d9b574049a6540f264a218ff5bf8a4d84f535055',m.operation_no,m.work_key,m.description,m.estimated_hours,m.estimated_hours_source,encode(extensions.digest(jsonb_build_object('source_hash','141354ac4a92cb01c031ee782450e56451061d7ba2f68b8fb79aca2a3d503a96','operation_no',m.operation_no,'work_key',m.work_key,'description',m.description)::text,'sha256'),'hex'),'J139125495',m.source_row_no,'pmb-email-communications-v1' FROM pdc479_manifest m WHERE NOT EXISTS(SELECT 1 FROM public.pdc_authenticated_email_operation_lines l WHERE l.source_hash='141354ac4a92cb01c031ee782450e56451061d7ba2f68b8fb79aca2a3d503a96' AND l.operation_no=m.operation_no) RETURNING operation_line_id,operation_no) INSERT INTO pdc479_inserted SELECT * FROM ins;
UPDATE public.pdc_authenticated_email_operation_lines l SET job_card_number='J139125495',source_row_no=m.source_row_no,source_contract='pmb-email-communications-v1' FROM pdc479_manifest m WHERE l.source_hash='141354ac4a92cb01c031ee782450e56451061d7ba2f68b8fb79aca2a3d503a96' AND l.operation_no=m.operation_no AND (l.job_card_number,l.source_row_no,l.source_contract) IS DISTINCT FROM ('J139125495',m.source_row_no,'pmb-email-communications-v1');
INSERT INTO public.audit_events(action,table_name,row_id,vehicle_id,actor_id,actor_email,before_data,after_data,metadata) SELECT 'insert','pdc_authenticated_email_operation_lines',l.operation_line_id,l.vehicle_id,'8a83b715-8d79-4b0e-95b2-02b55da6e8d7'::uuid,'craig.watson@broometoyota.com.au',null,to_jsonb(l),jsonb_build_object('source','uid632_operation_completeness_479','provider_uid','imap_uid:632','original_receipt_id','e7571359-c84c-493f-8376-d8384ea70b6f','no_booking',true,'unknown_not_zero',l.estimated_hours IS NULL) FROM pdc479_inserted i JOIN public.pdc_authenticated_email_operation_lines l USING(operation_line_id);
WITH requested(work_key) AS(VALUES('electrical'::text),('sublet'::text)),ins AS(INSERT INTO public.vehicle_work_items(vehicle_id,work_key,required,completed,completed_by,completed_at,notes,updated_at) SELECT '99518513-5293-5619-a06e-9b4323754838'::uuid,r.work_key,true,false,null,null,null,clock_timestamp() FROM requested r ON CONFLICT(vehicle_id,work_key) DO UPDATE SET required=true,updated_at=clock_timestamp() WHERE NOT public.vehicle_work_items.completed AND NOT public.vehicle_work_items.required RETURNING *) INSERT INTO public.audit_events(action,table_name,row_id,vehicle_id,actor_id,actor_email,before_data,after_data,metadata) SELECT 'insert','vehicle_work_items',id,vehicle_id,'8a83b715-8d79-4b0e-95b2-02b55da6e8d7'::uuid,'craig.watson@broometoyota.com.au',null,to_jsonb(ins),jsonb_build_object('source','uid632_operation_completeness_479','required_work',work_key,'completed_work_reopened',false,'no_booking',true) FROM ins;
CREATE TABLE public.pdc_uid632_operation_completeness_receipts_479(receipt_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),action_key text NOT NULL UNIQUE CHECK(action_key='uid632-complete-operations-479'),original_jobcard_receipt_id uuid NOT NULL REFERENCES public.pdc_jobcard_attachment_import_receipts(receipt_id) ON DELETE RESTRICT,vehicle_id uuid NOT NULL REFERENCES public.vehicles(id) ON DELETE RESTRICT,source_hash text NOT NULL CHECK(source_hash='141354ac4a92cb01c031ee782450e56451061d7ba2f68b8fb79aca2a3d503a96'),manifest_sha256 text NOT NULL CHECK(manifest_sha256='9b08ff6349ac522b0f5e5e023aca930452b5a02940965979f6c18cb69e3b2e47'),operation_count integer NOT NULL CHECK(operation_count=22),explicit_zero_count integer NOT NULL CHECK(explicit_zero_count=9),unknown_hours_count integer NOT NULL CHECK(unknown_hours_count=2),mapping_review_count integer NOT NULL CHECK(mapping_review_count=9),estimated_known_hours_sum numeric(10,2) NOT NULL CHECK(estimated_known_hours_sum=15.11),operation_manifest jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());ALTER TABLE public.pdc_uid632_operation_completeness_receipts_479 ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.pdc_uid632_operation_completeness_receipts_479 FROM public,anon,authenticated,service_role;INSERT INTO public.pdc_uid632_operation_completeness_receipts_479(action_key,original_jobcard_receipt_id,vehicle_id,source_hash,manifest_sha256,operation_count,explicit_zero_count,unknown_hours_count,mapping_review_count,estimated_known_hours_sum,operation_manifest) SELECT 'uid632-complete-operations-479','e7571359-c84c-493f-8376-d8384ea70b6f'::uuid,'99518513-5293-5619-a06e-9b4323754838'::uuid,'141354ac4a92cb01c031ee782450e56451061d7ba2f68b8fb79aca2a3d503a96','9b08ff6349ac522b0f5e5e023aca930452b5a02940965979f6c18cb69e3b2e47',22,9,2,9,15.11,jsonb_agg(jsonb_build_object('source_row_no',source_row_no,'operation_no',operation_no,'work_key',work_key,'description',description,'estimated_hours',estimated_hours,'estimated_hours_source',estimated_hours_source) ORDER BY source_row_no) FROM pdc479_manifest;
INSERT INTO public.pdc_email_operation_mapping_reviews_478(receipt_id,operation_line_id,operation_no,reason) SELECT 'e7571359-c84c-493f-8376-d8384ea70b6f'::uuid,l.operation_line_id,l.operation_no,'station mapping is not established by an existing Craig-approved durable rule' FROM public.pdc_authenticated_email_operation_lines l WHERE l.source_hash='141354ac4a92cb01c031ee782450e56451061d7ba2f68b8fb79aca2a3d503a96' AND l.work_key='owner_supplied_document' ON CONFLICT(operation_line_id) DO NOTHING;
DO $post$ BEGIN IF (SELECT count(*) FROM pdc479_inserted)<>14 OR (SELECT count(*) FROM public.pdc_authenticated_email_operation_lines WHERE source_hash='141354ac4a92cb01c031ee782450e56451061d7ba2f68b8fb79aca2a3d503a96')<>22 OR (SELECT count(*) FROM public.pdc_email_operation_mapping_reviews_478 WHERE receipt_id='e7571359-c84c-493f-8376-d8384ea70b6f'::uuid AND status='pending')<>9 OR (SELECT count(*) FROM public.vehicle_work_items WHERE vehicle_id='99518513-5293-5619-a06e-9b4323754838'::uuid AND required AND NOT completed AND work_key IN('fitting','fabrication','tyre','electrical','sublet'))<>5 OR EXISTS(SELECT 1 FROM public.workshop_bookings WHERE vehicle_id='99518513-5293-5619-a06e-9b4323754838'::uuid) THEN RAISE EXCEPTION 'PDC_479_POSTCONDITION_FAILED';END IF;END $post$;
INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES('20260827029000','479_uid632_complete_operations',ARRAY['Preserve the immutable original 8-line receipt and add an authoritative 22-line completeness successor','Retain 9 explicit zero-hour source lines and 2 unknown-hour lines as NULL, never zero','Map only operations established by current durable Craig-approved rules; keep 9 unknown station lines in pending mapping review','Add Electrical and Sublet requirements without bookings, completions or notifications','Production untouched']);COMMIT;
